package com.company.generated.units.u6d24746bc47a;

import java.math.BigDecimal;
import java.sql.CallableStatement;
import java.sql.Connection;
import java.sql.Types;
import java.util.Map;

public class ExecuteTransferStep {

    private static final String SP_NAME =
        "{call PKG_TRANSFERS.EXECUTE_TRANSFER(?,?,?,?,?,?,?,?,?,?)}";

    private static final int RC_SUCCESS   = 0;
    private static final int RC_REJECTED  = 6;
    private static final int RC_DUPLICATE = 7;
    private static final int RC_DB_ERROR  = 8;

    public int execute(Map<String, Object> context) throws Exception {
        String     sourceAccount = (String)     context.get("SourceAccount");
        String     targetAccount = (String)     context.get("TargetAccount");
        BigDecimal amount        = (BigDecimal) context.get("Amount");
        String     currency      = (String)     context.get("Currency");
        String     reference     = (String)     context.get("TransferReference");

        Connection conn = (Connection) context.get("Connection");
        if (conn == null) {
            throw new IllegalStateException("Configure a JDBC connection before executing a database step");
        }

        try (CallableStatement cs = conn.prepareCall(SP_NAME)) {
            cs.setString(    1, sourceAccount);
            cs.setString(    2, targetAccount);
            cs.setBigDecimal(3, amount);
            cs.setString(    4, currency != null ? currency.trim() : "ILS");
            cs.setString(    5, reference);

            cs.registerOutParameter(6,  Types.VARCHAR);
            cs.registerOutParameter(7,  Types.VARCHAR);
            cs.registerOutParameter(8,  Types.VARCHAR);
            cs.registerOutParameter(9,  Types.DATE);
            cs.registerOutParameter(10, Types.NUMERIC);

            cs.execute();

            String spRc = cs.getString(6);
            if ("REJECTED".equals(spRc))  return RC_REJECTED;
            if ("DUPLICATE".equals(spRc)) return RC_DUPLICATE;

            context.put("TransferId",       cs.getString(7));
            context.put("TransferStatus",   cs.getString(8));
            context.put("ExecutionDate",    cs.getDate(9));
            context.put("ExecutionTime",    new java.util.Date());
            context.put("NewSourceBalance", cs.getBigDecimal(10));

        } catch (Exception e) {
            context.put("DatabaseError", e.getMessage());
            return RC_DB_ERROR;
        }
        return RC_SUCCESS;
    }
}

package com.company.generated.units.u6d24746bc47a;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.sql.CallableStatement;
import java.sql.Connection;
import java.sql.Date;
import java.sql.Types;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

public class ExecuteTransferStepTest {

    @Test
    public void testSuccessfulTransfer() throws Exception {
        ExecuteTransferStep step = new ExecuteTransferStep();
        Map<String, Object> context = new HashMap<>();
        context.put("SourceAccount", "12345");
        context.put("TargetAccount", "67890");
        context.put("Amount", new BigDecimal("100.00"));
        context.put("Currency", "USD");
        context.put("TransferReference", "REF-001");

        Connection conn = mock(Connection.class);
        CallableStatement cs = mock(CallableStatement.class);
        when(conn.prepareCall(anyString())).thenReturn(cs);
        when(cs.getString(6)).thenReturn("SUCCESS");
        when(cs.getString(7)).thenReturn("T-999");
        when(cs.getString(8)).thenReturn("COMPLETED");
        when(cs.getDate(9)).thenReturn(new Date(System.currentTimeMillis()));
        when(cs.getBigDecimal(10)).thenReturn(new BigDecimal("900.00"));

        context.put("Connection", conn);

        int rc = step.execute(context);
        assertEquals(0, rc);
        assertEquals("T-999", context.get("TransferId"));
        assertEquals("COMPLETED", context.get("TransferStatus"));
        assertNotNull(context.get("ExecutionTime"));
        assertEquals(new BigDecimal("900.00"), context.get("NewSourceBalance"));
    }

    @Test
    public void testRejectedTransfer() throws Exception {
        ExecuteTransferStep step = new ExecuteTransferStep();
        Map<String, Object> context = new HashMap<>();
        context.put("SourceAccount", "12345");
        context.put("TargetAccount", "67890");
        context.put("Amount", new BigDecimal("100.00"));
        context.put("Currency", "USD");
        context.put("TransferReference", "REF-002");

        Connection conn = mock(Connection.class);
        CallableStatement cs = mock(CallableStatement.class);
        when(conn.prepareCall(anyString())).thenReturn(cs);
        when(cs.getString(6)).thenReturn("REJECTED");

        context.put("Connection", conn);

        int rc = step.execute(context);
        assertEquals(6, rc);
    }

    @Test
    public void testDuplicateTransfer() throws Exception {
        ExecuteTransferStep step = new ExecuteTransferStep();
        Map<String, Object> context = new HashMap<>();
        context.put("SourceAccount", "12345");
        context.put("TargetAccount", "67890");
        context.put("Amount", new BigDecimal("100.00"));
        context.put("Currency", "USD");
        context.put("TransferReference", "REF-003");

        Connection conn = mock(Connection.class);
        CallableStatement cs = mock(CallableStatement.class);
        when(conn.prepareCall(anyString())).thenReturn(cs);
        when(cs.getString(6)).thenReturn("DUPLICATE");

        context.put("Connection", conn);

        int rc = step.execute(context);
        assertEquals(7, rc);
    }

    @Test
    public void testDatabaseError() throws Exception {
        ExecuteTransferStep step = new ExecuteTransferStep();
        Map<String, Object> context = new HashMap<>();
        context.put("SourceAccount", "12345");
        context.put("TargetAccount", "67890");
        context.put("Amount", new BigDecimal("100.00"));
        context.put("Currency", "USD");
        context.put("TransferReference", "REF-004");

        Connection conn = mock(Connection.class);
        when(conn.prepareCall(anyString())).thenThrow(new RuntimeException("DB Failure"));

        context.put("Connection", conn);

        int rc = step.execute(context);
        assertEquals(8, rc);
        assertEquals("DB Failure", context.get("DatabaseError"));
    }

    @Test
    public void testMissingConnection() {
        ExecuteTransferStep step = new ExecuteTransferStep();
        Map<String, Object> context = new HashMap<>();
        assertThrows(IllegalStateException.class, () -> step.execute(context));
    }
}

